    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let capacity = bin_capacity.max(1) as f64;
    let residual_fraction = post_residual as f64 / capacity;
    let mean_fraction = (mean_residual / capacity).clamp(0.0, 1.0);
    let empty_bin = bin_residual >= bin_capacity;

    let mut score = post_residual as f64;
    let progress_centered = progress - 0.5;
    let progress_sq = progress_centered * progress_centered;

    score += 42.0 * residual_fraction * (1.0 - progress);
    score -= 18.0 * residual_fraction * progress;
    score -= 12.0 * residual_fraction * progress_sq;
    score -= 7.0 * residual_fraction * mean_fraction;

    let utilization_gain = item_size as f64 / capacity;
    score -= 15.0 * utilization_gain * (0.35 + 0.65 * progress);

    if next_item_size > 0 {
        let next_fraction = (next_item_size as f64 / capacity).clamp(0.0, 1.0);
        let compatibility = (residual_fraction - next_fraction).max(0.0);
        score += 28.0 * compatibility * (1.0 - 0.45 * progress);
        score -= 9.0 * residual_fraction * next_fraction * progress;
    }

    if fitting_bins_count <= 1 {
        score -= 20.0 * (1.0 - residual_fraction);
    }

    if empty_bin {
        score += 26.0 + 14.0 * progress + 18.0 * mean_fraction;
        score -= 10.0 * open_bins_count as f64 / (open_bins_count.max(1) as f64).sqrt();
    }

    score += 3.0 * (mean_residual - bin_residual as f64);
    score
}

