pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let mean = mean_residual.max(0.0);
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 + 1.0) / total_items as f64
    };

    let is_new_bin = bin_residual >= bin_capacity;
    let fill_before = if capacity > 0.0 {
        (capacity - residual) / capacity
    } else {
        0.0
    };
    let fill_after = if capacity > 0.0 {
        1.0 - score / capacity
    } else {
        0.0
    };

    // Tight, high-utilization placements are generally preferable.
    score += 0.65 * (1.0 - fill_after).powi(2);

    // Fragmentation penalty: small residual pockets are difficult to reuse.
    if score < 20.0 {
        score += (20.0 - score) * (0.9 + 0.8 * (1.0 - progress));
    }

    // Look-ahead: retain room for the following item when practical.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if score >= next {
            let surplus = score - next;
            score += 0.18 * surplus.min(35.0);
        } else {
            score += 5.0 * (1.0 - progress) * (1.0 - fill_before);
        }
    }

    // A lone fitting bin deserves special care because rejecting it may open a bin.
    if fitting_bins_count <= 1 && !is_new_bin {
        score -= 2.5 + 4.0 * (1.0 - progress);
    }

    // Prefer placements close to the global residual profile; this discourages
    // creating outliers among otherwise similar open bins.
    if !is_new_bin {
        score += 0.055 * (score - mean).abs();
    } else {
        // Opening a new bin is attractive when current bins are poorly balanced,
        // but not merely because a particular bin happens to be available.
        score += 0.035 * mean;
        score += 0.7 * (1.0 - progress);
    }

    // Early in a long stream, preserve flexibility; later, consolidate tightly.
    score += 0.35 * progress * (1.0 - fill_after);
    score += 0.0025 * open_bins_count as f64;

    if is_new_bin {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let next = next_item_size as f64;
    let mean = mean_residual.max(0.0);
    let is_new_bin = bin_residual == bin_capacity;

    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).min(1.0)
    };

    let pressure = if open_bins_count == 0 || total_items == 0 {
        0.0
    } else {
        (open_bins_count as f64 / total_items as f64).min(1.0)
    };

    let mut score;

    if is_new_bin {
        let fragmentation = if mean > 0.0 {
            (mean / capacity).min(1.0)
        } else {
            0.5
        };

        let alternatives = fitting_bins_count as f64;
        let best_known_fit = if next > 0.0 {
            (next / capacity).min(1.0)
        } else {
            0.0
        };

        let new_bin_cost = 172.0
            + 20.0 * (item / capacity)
            + 34.0 * fragmentation
            + 12.0 * best_known_fit
            - 118.0 * pressure
            - 42.0 * progress;

        score = new_bin_cost + 0.16 * residual;

        if alternatives == 0.0 {
            score -= 135.0;
        } else if alternatives <= 1.0 {
            score -= 24.0;
        } else if alternatives <= 3.0 {
            score += 12.0;
        }
    } else {
        score = post_residual as f64;

        if post_residual == 0 {
            score -= 132.0;
        } else if post_residual <= 3 {
            score -= 68.0;
        } else if post_residual <= 8 {
            score -= 31.0;
        }

        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 47.0;
                let surplus = (post_residual - next_item_size) as f64;
                score -= 14.0 * (surplus / capacity).min(1.0);

                if post_residual <= next_item_size + 3 {
                    score -= 16.0;
                }
            } else {
                score += 41.0;
                let deficit = (next_item_size - post_residual) as f64;
                score += 27.0 * (deficit / capacity).min(1.0);
            }
        }

        if post_residual > 0 && post_residual < item.min(9) {
            score += 25.0 + 13.0 * progress;
        }

        if mean > 0.0 {
            let deviation = post_residual as f64 - mean;
            score += 0.24 * deviation.abs();
            if post_residual as f64 > mean {
                score += 0.10 * (post_residual as f64 - mean);
            }
        }

        if fitting_bins_count <= 1 {
            score -= 23.0 + 0.30 * item;
        }

        score -= 9.0 * pressure;

        let lookahead_window = (1.0 - 0.55 * progress).max(0.45);
        score += lookahead_window * 0.16 * post_residual as f64;
    }

    score -= 19.0 * (item / capacity);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let pressure = if open_bins_count == 0 {
        0.0
    } else {
        (open_bins_count as f64 / total_items.max(1) as f64).min(1.0)
    };

    if is_new_bin {
        score += 220.0;
        score -= 80.0 * pressure;
    } else {
        let dead_gap = post_residual.min(next_item_size.saturating_sub(1));
        score += 2.8 * dead_gap as f64;

        if post_residual == 0 {
            score -= 45.0;
        } else if post_residual < 10 {
            score += 120.0;
        } else if post_residual < next_item_size && next_item_size > 0 {
            score += 35.0 * (next_item_size - post_residual) as f64;
        }

        if fitting_bins_count == 1 {
            score -= 65.0;
        }

        score -= 18.0 * (pressure * 100.0).min(100.0) / 100.0;
    }

    let utilization_delta = if bin_capacity > 0 {
        item_size as f64 / bin_capacity as f64
    } else {
        0.0
    };
    score -= 25.0 * utilization_delta;

    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}
